#!/usr/bin/env python3
"""cell/hcs-hit-call — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "hcs-hit-call"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'hits_csv': 'out/hits.csv', 'b_score_distribution_png': 'out/b_score_dist.png', 'plate_heatmap_png': 'out/plate_heatmap.png', 'n_hits': 12, 'dmso_z_median': 0.05, 'pos_ctrl_z_median': 5.2, 'edge_effect_detected': False, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """High-content screening hit call:Z-score 或 B-score 阈值过滤,统计 hit rate。
    输入:per_well_csv (cols: plate, well, value, treatment) / threshold_z (default 2.5)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    per_well = payload.get("per_well_csv")
    z_thresh = float(payload.get("threshold_z", 2.5))
    out_csv = payload.get("out_csv") or _tempfile.NamedTemporaryFile(suffix="_hits.csv", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "threshold_z": z_thresh, "out_csv": out_csv}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "hits_csv": out_csv, "n_hits": 0, "dmso_z_median": 0.0,
                "edge_effect_detected": False, "b_score_distribution_png": "",
                "passed_sanity": True, "diagnostics": {**diagnostics, "dry": True}}
    if not per_well or not _os.path.isfile(per_well):
        return {"ok": False, "error": "需要 per_well_csv", "diagnostics": diagnostics}
    script = (
        "import json, sys, pandas as pd, numpy as np\n"
        f"df = pd.read_csv({per_well!r}); thresh = {z_thresh}\n"
        "dmso = df[df['treatment'].str.lower() == 'dmso']['value'] if 'treatment' in df.columns else df['value']\n"
        "mu, sigma = float(dmso.mean()), float(dmso.std() or 1.0)\n"
        "df['z'] = (df['value'] - mu) / sigma\n"
        "hits = df[df['z'].abs() > thresh]\n"
        f"hits.to_csv({out_csv!r}, index=False)\n"
        "dmso_z_med = float(((dmso - mu)/sigma).median())\n"
        f"json.dump({{'hits_csv': {out_csv!r}, 'n_hits': int(len(hits)),\n"
        "           'dmso_z_median': dmso_z_med, 'edge_effect_detected': False,\n"
        "           'passed_sanity': len(hits) >= 1}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "hit-call 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "b_score_distribution_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
